/**
 * Hausa locale (ha) - implemented in 4.2.0 from docs/locales/ha-SPEC.md
 * (sources quoted there). Distinctive: the multiplier FOLLOWS the scale word
 * ("ɗari biyu", "dubu biyu", "miliyan ɗaya") and EVERY nonzero component is
 * joined by "da". Scale loans: miliyan/biliyan/tiriliyan; beyond 10^12 the
 * locale code-switches to the English Conway-Wechsler name (documented media
 * practice, SPEC §6).
 *
 * Words for 0..99 are GENERATED by the rules below. Ordinals and decimals are
 * OPEN items (see SPEC §7): decimal inputs reject loudly; currency mode works.
 */

import { illionName } from "../illions.js";
import type { LocaleDefinition } from "./types.js";

const UNITS = [
  "ɗaya",
  "biyu",
  "uku",
  "huɗu",
  "biyar",
  "shida",
  "bakwai",
  "takwas",
  "tara",
] as const;

const TENS = [
  "ashirin",
  "talatin",
  "arba'in",
  "hamsin",
  "sittin",
  "saba'in",
  "tamanin",
  "casa'in",
] as const;

/** Builds the 0..99 word table from the verified rules (SPEC §3). */
function buildSmallNumbers(): string[] {
  const table: string[] = [];

  table[0] = "sifili";
  UNITS.forEach((word, index) => {
    table[index + 1] = word;
  });

  table[10] = "goma";
  UNITS.forEach((word, index) => {
    table[11 + index] = `goma sha ${word}`; // 11-19: goma sha ɗaya ... goma sha tara
  });

  TENS.forEach((stem, tensIndex) => {
    const base = 20 + tensIndex * 10;
    table[base] = stem;
    UNITS.forEach((word, index) => {
      table[base + 1 + index] = `${stem} da ${word}`; // ashirin da ɗaya ...
    });
  });

  return table;
}

/** Hausa attested scale loans; beyond 10^12 the English name is used (SPEC §6). */
function haScaleName(groupIndex: number): string {
  switch (groupIndex) {
    case 2:
      return "miliyan"; // 10^6
    case 3:
      return "biliyan"; // 10^9
    case 4:
      return "tiriliyan"; // 10^12
    default:
      return illionName(groupIndex - 1).toLowerCase(); // documented English code-switch
  }
}

/** Multiplier-after order: "miliyan ɗaya", "miliyan biyu" (SPEC §4). */
function haScaleWord(groupIndex: number, _groupValue: number, groupWords: string): string {
  return `${haScaleName(groupIndex)} ${groupWords}`;
}

export const haLocale: LocaleDefinition = {
  code: "ha",
  zeroWord: "sifili",
  smallNumbers: buildSmallNumbers(),
  hundredWord: "ɗari",
  thousandWord: "dubu",
  negativePrefix: "(negative) ", // OPEN ITEM (SPEC §2): unlocalized pending a source
  dotSeparator: "(dot) ", // unreachable - decimals are rejected (SPEC §7)
  andStyle: "british",
  andWord: "da", // ɗari da hamsin, dubu ɗaya da ɗari
  supportsBothStyles: false,
  groupSeparator: " da ",
  scaleWordFor: haScaleWord,
  thousandPhraseFor: (groupValue, groupWords) =>
    groupValue === 1 ? "dubu ɗaya" : `dubu ${groupWords}`,
  hundredPhraseFor: (hundreds) =>
    hundreds === 1 ? "ɗari" : `ɗari ${UNITS[hundreds - 1]}`,
};
